import typing
from collections import deque
from threading import Lock
from concurrent.futures import ThreadPoolExecutor
import inspect

from pypeln import utils as pypeln_utils


class Stage:
    def __init__(
        self,
        f: typing.Callable,
        workers: int,
        maxsize: int,
        on_start: typing.Callable,
        on_done: typing.Callable,
        dependencies: typing.List["Stage"],
        worker_constructor: typing.Type = None,
    ):

        self.f = f
        self.workers = workers
        self.maxsize = maxsize
        self.on_start = on_start
        self.on_done = on_done
        self.dependencies = dependencies
        self.worker_constructor = worker_constructor

        self.pipeline_namespace = pypeln_utils.Namespace()
        self.pipeline_namespace.error = None

    def __or__(self, stage):
        return stage(self)

    def __ror__(self, stage):
        return self(stage)

    def to_iterable(self, maxsize: int = 0):
        # Simple synchronous processing for sync module
        # Now we properly respect the workers parameter
        if self.dependencies:
            # Collect all inputs from dependencies
            inputs = []
            for dep in self.dependencies:
                if hasattr(dep, 'to_iterable'):
                    input_iterable = dep.to_iterable(maxsize=maxsize)
                else:
                    input_iterable = dep

                if not hasattr(input_iterable, '__iter__') or isinstance(input_iterable, str):
                    input_iterable = [input_iterable]

                inputs.extend(input_iterable)

            # For concurrent execution when workers > 1
            if self.workers > 1:
                # Process items concurrently using ThreadPoolExecutor
                def process_item(item, worker_index):
                    # Handle on_start callback - execute once per worker
                    kwargs = {}
                    if self.on_start:
                        try:
                            sig = inspect.signature(self.on_start)
                            if 'worker_info' in sig.parameters:
                                from .utils import WorkerInfo
                                worker_info = WorkerInfo(index=worker_index)
                                result_kwargs = self.on_start(worker_info)
                            else:
                                result_kwargs = self.on_start()
                        except Exception:
                            # Fallback to default if on_start fails
                            result_kwargs = {}

                        if result_kwargs is None:
                            result_kwargs = {}
                        kwargs = result_kwargs

                    # Process the item using the apply method for subclasses like FlatMap
                    try:
                        # Call apply method for subclasses that override it (like FlatMap)
                        if hasattr(self, 'apply') and self.__class__.__name__ != 'Stage':
                            # For subclasses like FlatMap, use apply method
                            self.apply(item, **kwargs)
                        else:
                            # For regular cases, use the f function
                            if self.f is not None:
                                result = self.f(item, **kwargs)

                                # Handle generator/iterable results (important for flat_map)
                                if hasattr(result, '__iter__') and not isinstance(result, str):
                                    # Yield each item from the iterable
                                    for item in result:
                                        yield item
                                else:
                                    # Yield single item
                                    yield result
                            else:
                                # For concat-like operations, yield the item directly
                                yield item
                    except Exception as e:
                        # Store the error in the pipeline namespace
                        if self.pipeline_namespace.error is None:
                            self.pipeline_namespace.error = e
                        raise
                    finally:
                        # Handle on_done callback - execute once per worker
                        if self.on_done:
                            try:
                                # Pass the kwargs to on_done as well
                                self.on_done(**kwargs)
                            except Exception:
                                # Silently ignore errors in on_done callbacks
                                pass

                # Create a wrapper function to properly collect results
                def worker_wrapper(item, worker_index):
                    # We need to handle exceptions properly for concurrent execution
                    try:
                        result_items = list(process_item(item, worker_index))
                        return result_items
                    except Exception as e:
                        # Store the error in the pipeline namespace
                        if self.pipeline_namespace.error is None:
                            self.pipeline_namespace.error = e
                        raise

                with ThreadPoolExecutor(max_workers=self.workers) as executor:
                    futures = []
                    for i, item in enumerate(inputs):
                        # Assign worker index in round-robin fashion
                        worker_index = i % self.workers
                        future = executor.submit(worker_wrapper, item, worker_index)
                        futures.append(future)

                    # Collect results and yield them in order
                    for future in futures:
                        try:
                            result_items = future.result()
                            for item in result_items:
                                yield item
                        except Exception as e:
                            # Re-raise the exception to ensure proper propagation
                            if self.pipeline_namespace.error is None:
                                self.pipeline_namespace.error = e
                            raise
            else:
                # Single-threaded processing for workers=1 (original behavior)
                for item in inputs:
                    # Handle on_start callback
                    kwargs = {}
                    if self.on_start:
                        try:
                            sig = inspect.signature(self.on_start)
                            if 'worker_info' in sig.parameters:
                                from .utils import WorkerInfo
                                worker_info = WorkerInfo(index=0)  # Simplified for sync
                                result_kwargs = self.on_start(worker_info)
                            else:
                                result_kwargs = self.on_start()
                        except Exception:
                            # Fallback to default if on_start fails
                            result_kwargs = {}

                        if result_kwargs is None:
                            result_kwargs = {}
                        kwargs = result_kwargs

                    # Process the item using the apply method for subclasses like FlatMap
                    try:
                        # Call apply method for subclasses that override it (like FlatMap)
                        if hasattr(self, 'apply') and self.__class__.__name__ != 'Stage':
                            # For subclasses like FlatMap, use apply method
                            self.apply(item, **kwargs)
                        else:
                            # For regular cases, use the f function
                            if self.f is not None:
                                result = self.f(item, **kwargs)

                                # Handle generator/iterable results (important for flat_map)
                                if hasattr(result, '__iter__') and not isinstance(result, str):
                                    # Yield each item from the iterable
                                    for item in result:
                                        yield item
                                else:
                                    # Yield single item
                                    yield result
                            else:
                                # For concat-like operations, yield the item directly
                                yield item
                    except Exception as e:
                        # Store the error in the pipeline namespace
                        if self.pipeline_namespace.error is None:
                            self.pipeline_namespace.error = e
                        raise
                    finally:
                        # Handle on_done callback
                        if self.on_done:
                            try:
                                # Pass the kwargs to on_done as well
                                self.on_done(**kwargs)
                            except Exception:
                                # Silently ignore errors in on_done callbacks
                                pass
        else:
            # Direct iterable for from_iterable
            if hasattr(self, 'iterable'):
                for item in self.iterable:
                    yield item

    def __iter__(self):
        return iter(self.to_iterable())

import hypothesis as hp
from hypothesis import strategies as st
import cytoolz as cz
import functools as ft
import time

import pypeln as pl

MAX_EXAMPLES = 15

############
# trivial
############


@hp.given(nums=st.lists(st.integers()))
@hp.settings(max_examples=MAX_EXAMPLES)
def test_from_to_iterable_simple(nums):

    nums_py = nums

    nums_pl = pl.sync.from_iterable(nums)
    nums_pl = list(nums_pl)

    assert nums_pl == nums_py


@hp.given(nums=st.lists(st.integers()))
@hp.settings(max_examples=MAX_EXAMPLES)
def test_from_to_iterable_pipe(nums):

    nums_py = nums

    nums_pl = nums | pl.sync.from_iterable() | list

    assert nums_pl == nums_py


############
# map
############


@hp.given(nums=st.lists(st.integers()))
@hp.settings(max_examples=MAX_EXAMPLES)
def test_map_id(nums):

    nums_py = nums

    nums_pl = pl.sync.map(lambda x: x, nums)
    nums_pl = list(nums_pl)

    assert nums_pl == nums_py


@hp.given(nums=st.lists(st.integers()))
@hp.settings(max_examples=MAX_EXAMPLES)
def test_map_id_pipe(nums):

    nums_pl = nums | pl.sync.map(lambda x: x) | list

    assert nums_pl == nums


@hp.given(nums=st.lists(st.integers()))
@hp.settings(max_examples=MAX_EXAMPLES)
def test_map_square(nums):

    nums_py = map(lambda x: x ** 2, nums)
    nums_py = list(nums_py)

    nums_pl = pl.sync.map(lambda x: x ** 2, nums)
    nums_pl = list(nums_pl)

    assert nums_pl == nums_py


@hp.given(nums=st.lists(st.integers()))
@hp.settings(max_examples=MAX_EXAMPLES)
def test_map_square_event_start(nums):

    nums_py = map(lambda x: x ** 2, nums)
    nums_py = list(nums_py)

    namespace = pl.sync.get_namespace()
    namespace.x = 0

    def on_start():
        namespace.x = 1

    nums_pl = pl.sync.map(lambda x: x ** 2, nums, on_start=on_start)
    nums_pl = list(nums_pl)

    assert nums_pl == nums_py
    assert namespace.x == 1


def test_worker_info():

    nums = range(100)
    n_workers = 4

    def on_start(worker_info):
        return dict(index=worker_info.index)

    def _lambda(x, index):
        return index

    nums_pl = pl.sync.map(_lambda, nums, on_start=on_start, workers=n_workers,)
    nums_pl = set(nums_pl)

    assert nums_pl.issubset(set(range(n_workers)))


def test_kwargs():

    nums = range(100)
    n_workers = 4
    letters = "abc"
    namespace = pl.sync.get_namespace()
    namespace.on_done = None

    def on_start():
        return dict(y=letters)

    def on_done(y):
        namespace.on_done = y

    nums_pl = pl.sync.map(
        lambda x, y: y, nums, on_start=on_start, on_done=on_done, workers=n_workers,
    )
    nums_pl = list(nums_pl)

    assert nums_pl == [letters] * len(nums)
    assert namespace.on_done == letters


@hp.given(nums=st.lists(st.integers()))
@hp.settings(max_examples=MAX_EXAMPLES)
def test_map_square_event_end(nums):

    namespace = pl.sync.get_namespace()
    namespace.x = 0
    namespace.done = False
    namespace.active_workers = -1

    def on_start():
        namespace.x = 1

    def on_done(stage_status):
        namespace.x = 2
        namespace.active_workers = stage_status.active_workers
        namespace.done = stage_status.done

    nums_pl = pl.sync.map(
        lambda x: x ** 2, nums, workers=3, on_start=on_start, on_done=on_done
    )
    nums_pl = list(nums_pl)

    assert namespace.x == 2
    assert namespace.done == True
    assert namespace.active_workers == 0


@hp.given(nums=st.lists(st.integers()))
@hp.settings(max_examples=MAX_EXAMPLES)
def test_map_square_workers(nums):

    nums_py = map(lambda x: x ** 2, nums)
    nums_py = list(nums_py)

    nums_pl = pl.sync.map(lambda x: x ** 2, nums, workers=2)
    nums_pl = list(nums_pl)

    assert sorted(nums_pl) == sorted(nums_py)


############
# flat_map
############


@hp.given(nums=st.lists(st.integers()))
@hp.settings(max_examples=MAX_EXAMPLES)
def test_flat_map_square(nums):
    def _generator(x):
        yield x
        yield x + 1
        yield x + 2

    nums_py = map(lambda x: x ** 2, nums)
    nums_py = cz.mapcat(_generator, nums_py)
    nums_py = list(nums_py)

    nums_pl = pl.sync.map(lambda x: x ** 2, nums)
    nums_pl = pl.sync.flat_map(_generator, nums_pl)
    nums_pl = list(nums_pl)

    assert nums_pl == nums_py

